// Merge Adzuna (JSON) + onlinejobs.ph (HTML, best-effort) into unified postings.
const MNL = 'Asia/Manila';
const nowIso = () => new Date().toISOString();

// lead = a company hiring in-house (pitch them to outsource); gig = a contract to apply to.
function classify(text) {
  const t = (text || '').toLowerCase();
  const gig = /(contract|freelance|freelancer|project[- ]based|part[- ]time|remote gig|per hour|hourly|\/hr)/;
  const lead = /(hiring|we're looking|were looking|join our team|in[- ]house|full[- ]time|seeking a|looking for a)/;
  if (gig.test(t)) return 'gig';
  if (lead.test(t)) return 'lead';
  return 'gig';
}

const out = [];

// ── Adzuna ──
try {
  const a = $('Adzuna').first().json;
  const rows = (a && a.results) || [];
  for (const r of rows) {
    if (!r || !r.redirect_url) continue;
    const title = r.title || '';
    out.push({
      source: 'adzuna',
      external_id: String(r.id || ''),
      url: r.redirect_url,
      title: title.replace(/<[^>]+>/g, '').trim(),
      company: (r.company && r.company.display_name) || null,
      location: (r.location && r.location.display_name) || null,
      remote: /remote/i.test(title + ' ' + ((r.location && r.location.display_name) || '')),
      category: (r.category && r.category.label) || null,
      tag: classify(title + ' ' + (r.description || '')),
      salary_text: r.salary_min ? ('$' + Math.round(r.salary_min) + (r.salary_max ? '–$' + Math.round(r.salary_max) : '')) : null,
      posted_at: r.created || nowIso(),
      description: (r.description || '').replace(/<[^>]+>/g, '').slice(0, 500),
    });
  }
} catch (e) { /* Adzuna failed — carry on with onlinejobs */ }

// ── onlinejobs.ph (best-effort HTML scrape) ──
try {
  const html = $('OnlineJobs.ph').first().json;
  const body = typeof html === 'string' ? html : (html && (html.data || html.body)) || '';
  const re = /href=\"(\/jobseekers\/job\/[^\"]+)\"[^>]*>\s*([^<]{4,140})</g;
  let match; const seen = new Set();
  while ((match = re.exec(body)) !== null) {
    const url = 'https://www.onlinejobs.ph' + match[1];
    if (seen.has(url)) continue; seen.add(url);
    const title = match[2].replace(/\s+/g, ' ').trim();
    out.push({
      source: 'onlinejobs', external_id: match[1], url, title,
      company: null, location: 'Philippines', remote: true, category: null,
      tag: classify(title), salary_text: null, posted_at: nowIso(), description: null,
    });
  }
} catch (e) { /* onlinejobs parse failed — Adzuna still delivered */ }

// De-dupe within this run by url.
const byUrl = new Map();
for (const p of out) if (p.url && !byUrl.has(p.url)) byUrl.set(p.url, p);
return [{ json: { postings: [...byUrl.values()] } }];

// Supabase returns ONLY newly-inserted rows (dupes ignored). Fan out one item
// per new posting for the Sheet, tagged with split date/time.
const MNL = 'Asia/Manila';
const rows = $input.all().map(i => i.json).flat().filter(r => r && r.url);
const fmt = (iso) => {
  const d = new Date(iso || Date.now());
  return {
    Date: new Intl.DateTimeFormat('en-CA', { timeZone: MNL, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d),
    Time: new Intl.DateTimeFormat('en-GB', { timeZone: MNL, hour: '2-digit', minute: '2-digit' }).format(d),
  };
};
return rows.map((r) => { const t = fmt(r.created_at); return { json: {
  Timestamp: r.created_at, Date: t.Date, Time: t.Time,
  Source: r.source, Tag: r.tag, Title: r.title, Company: r.company || '',
  Location: r.location || '', Remote: r.remote ? 'yes' : 'no',
  Salary: r.salary_text || '', PostedAt: r.posted_at || '', URL: r.url,
} }; });

// Recipients come from profiles (the Recipients node), never a hardcoded
// personal address: the mail follows whoever holds the role today, and a
// deactivated account (profiles.deactivated_at, migration 032) stops getting
// it. The company inbox is used only when nobody qualifies.
const FALLBACK_TO = 'nixgensolutions@gmail.com';
const EMAIL_RE = /^[^\s@,;<>"']+@[^\s@,;<>"']+\.[^\s@,;<>"']+$/;
const people = $('Recipients').all().map(i => i.json).flat()
  .filter(p => p && p.id && !p.deactivated_at && EMAIL_RE.test(String(p.email || '').trim()));
const can = (p, feature, level) => p.role === 'admin'
  || (p.permissions || {})[feature] === 'edit'
  || (level === 'view' && (p.permissions || {})[feature] === 'view');
const addressOf = (list) => [...new Set(list.map(p => String(p.email).trim().toLowerCase()))].join(',');
const TO = addressOf(people.filter(p => can(p, 'growth', 'edit'))) || FALLBACK_TO;
// Aggregate the new postings into one digest email. No new → no email.
const rows = $('New postings').all().map(i => i.json).filter(r => r && r.URL);
if (!rows.length) return [];
// Postings are third-party data (Adzuna, onlinejobs.ph): every value is
// escaped for text AND attributes, and a link is only ever an https URL.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const safeHttps = (u) => {
  try {
    const x = new URL(String(u ?? '').trim());
    return x.protocol === 'https:' && !x.username && !x.password ? x.href : '';
  } catch (e) {
    return '';
  }
};
const tagOf = (t) => (t === 'lead' ? 'lead' : 'gig');
const tr = rows.map((r) => `<tr>
  <td style=\"padding:6px 12px;border-bottom:1px solid #eee\"><span style=\"font-size:11px;text-transform:uppercase;color:${tagOf(r.Tag) === 'lead' ? '#2563eb' : '#0ea5e9'}\">${tagOf(r.Tag)}</span></td>
  <td style=\"padding:6px 12px;border-bottom:1px solid #eee\">${safeHttps(r.URL) ? `<a href=\"${esc(safeHttps(r.URL))}\">${esc(r.Title)}</a>` : esc(r.Title)}</td>
  <td style=\"padding:6px 12px;border-bottom:1px solid #eee;color:#666\">${esc(r.Company)}</td>
  <td style=\"padding:6px 12px;border-bottom:1px solid #eee;color:#666\">${esc(r.Location)}${r.Remote === 'yes' ? ' · Remote' : ''}</td>
</tr>`).join('');
const html = `<div style=\"font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:#111\">
  <h2 style=\"margin:0 0 4px\">DeskDev — ${rows.length} new job ${rows.length === 1 ? 'posting' : 'postings'}</h2>
  <p style=\"margin:0 0 16px;color:#666\">Leads to pitch and gigs to apply to. Manage them in Growth Hub → Job leads.</p>
  <table style=\"border-collapse:collapse;font-size:14px\">${tr}</table>
  <p style=\"margin-top:20px;color:#999;font-size:12px\">Sent by n8n · Adzuna + onlinejobs.ph</p></div>`;
return [{ json: { html, count: rows.length, to: TO } }];
